package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Normalizes the address of a create request to its canonical form (see
 * {@link AddressNormalizer#normalize(String)}) before any other rule runs. Running first means the
 * required-field check ({@link ValidateOwnerFields}) rejects an address that is blank after
 * normalization, the household comparisons ({@link EnsureUniqueHousehold}, {@link AssignHousehold})
 * compare normalized addresses, and {@link BuildOwner} stores — and later responses return — the
 * normalized form. Binds the request body once and republishes it for the rest of the pipeline.
 */
public class NormalizeAddress {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized) {
        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
        normalized.set(request);
    }
}
=== AssignCustomerCode ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's customerCode, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is the
 * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the last
 * name and NNNN a per-city 4-digit zero-padded sequence equal to one more than the owners already in
 * that city (e.g. {@code SYD-SMI-0007}). Runs before {@link SaveOwner}, so the count excludes the
 * owner currently being created. Mutates the built {@link Owner} in place.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String city = owner.getCity();
        long sequence = ownerRepository.findAll().stream()
                .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
                .count() + 1;
        owner.setCustomerCode(String.format("%s-%s-%04d", prefix(city), prefix(owner.getLastName()), sequence));
    }

    /** The upper-cased first three letters of the value (or fewer when it is shorter). */
    private static String prefix(String value) {
        return value.substring(0, Math.min(3, value.length())).toUpperCase();
    }
}
=== AssignHousehold ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * When the create request sets {@code sharesHousehold} true and the new owner joins a household
 * already occupied by an existing owner (same last name and address, see {@link HouseholdNormalizer}),
 * stamps the new owner and every existing member of that household with the same stable
 * {@link HouseholdNormalizer#id(String, String) household id}. Without {@code sharesHousehold} the
 * request never reaches here as a joiner — {@link EnsureUniqueHousehold} rejects the collision first —
 * so a lone owner keeps a null household id. Runs after {@link BuildOwner} and mutates the built
 * {@link Owner} in place; existing members are re-saved so a later read returns the shared id too.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String key = HouseholdNormalizer.key(owner.getLastName(), owner.getAddress());
        boolean joinsHousehold = false;
        String householdId = HouseholdNormalizer.id(owner.getLastName(), owner.getAddress());
        for (Owner member : ownerRepository.findAll()) {
            if (!key.equals(HouseholdNormalizer.key(member.getLastName(), member.getAddress()))) {
                continue;
            }
            joinsHousehold = true;
            if (!householdId.equals(member.getHouseholdId())) {
                member.setHouseholdId(householdId);
                ownerRepository.save(member);
            }
        }
        if (joinsHousehold) {
            owner.setHouseholdId(householdId);
        }
    }
}

